import { ancientTempleCourse } from '../courses/data/ancient-temple';
import { arcticBaseCourse } from '../courses/data/arctic-base';
import { candyFactoryCourse } from '../courses/data/candy-factory';
import { chaosDimension } from '../courses/data/chaos-dimension';
import { greenHillsCourse } from '../courses/data/green-hills';
import { hauntedMansion } from '../courses/data/haunted-mansion';
import { neonCity } from '../courses/data/neon-city';
import { pirateBayCourse } from '../courses/data/pirate-bay';
import { spaceStation } from '../courses/data/space-station';
import { volcanoCourse } from '../courses/data/volcano';
import type { Course } from '../courses/types';

/** Every playable course, ordered from gentle to chaotic. */
export const COURSES: readonly Course[] = [
  greenHillsCourse,
  pirateBayCourse,
  candyFactoryCourse,
  hauntedMansion,
  neonCity,
  ancientTempleCourse,
  arcticBaseCourse,
  volcanoCourse,
  spaceStation,
  chaosDimension,
];

export const DEFAULT_COURSE_ID = greenHillsCourse.id;

export function courseById(id: string): Course | undefined {
  return COURSES.find((course) => course.id === id);
}

/** Menu ids that do not match a course fall back to the starter course. */
export function resolveCourse(id: string, random: () => number = Math.random): Course {
  if (id === 'random') {
    const index = Math.min(COURSES.length - 1, Math.max(0, Math.floor(random() * COURSES.length)));
    return COURSES[index] ?? greenHillsCourse;
  }
  return courseById(id) ?? greenHillsCourse;
}

/** Trims a course to the requested hole count; hole ids stay unique. */
export function limitCourse(course: Course, holeCount: number): Course {
  const wanted = Math.max(1, Math.min(course.holes.length, Math.floor(holeCount)));
  return wanted === course.holes.length ? course : { ...course, holes: course.holes.slice(0, wanted) };
}
