import type { ControlScheme } from '../contracts/game';
import type { Vec3 } from '../contracts/math';
import type { InputSnapshot } from '../input/InputManager';

export interface AimSample {
  direction: Vec3;
  power: number;
  charging: boolean;
  fired: boolean;
}

const CHARGE_SECONDS = 1.15;
const MAX_DRAG_PIXELS = 260;
const MIN_DRAG_PIXELS = 8;
export const MIN_SHOT_POWER = 0.06;

const normalize = (x: number, z: number): Vec3 => {
  const length = Math.hypot(x, z);
  return length < 1e-6 ? { x: 0, y: 0, z: -1 } : { x: x / length, y: 0, z: z / length };
};

/**
 * Turns raw input into an aim direction and a 0..1 power value.
 * Both schemes aim relative to the camera yaw so the shot always leaves the camera.
 */
export class AimController {
  private scheme: ControlScheme;
  private direction: Vec3 = { x: 0, y: 0, z: -1 };
  private power = 0;
  private charging = false;
  private chargingUp = true;
  private anchorX = 0;
  private anchorY = 0;

  constructor(scheme: ControlScheme = 'hold-to-charge') {
    this.scheme = scheme;
  }

  get controlScheme(): ControlScheme {
    return this.scheme;
  }

  get isCharging(): boolean {
    return this.charging;
  }

  setScheme(scheme: ControlScheme): void {
    this.scheme = scheme;
    this.cancel();
  }

  cancel(): void {
    this.power = 0;
    this.charging = false;
    this.chargingUp = true;
  }

  update(dt: number, input: InputSnapshot, cameraYaw: number, enabled: boolean): AimSample {
    const forward = normalize(-Math.sin(cameraYaw), -Math.cos(cameraYaw));
    if (!enabled) {
      this.cancel();
      this.direction = forward;
      return { direction: forward, power: 0, charging: false, fired: false };
    }
    return this.scheme === 'drag-power'
      ? this.updateDrag(input, forward)
      : this.updateCharge(dt, input, forward);
  }

  private updateDrag(input: InputSnapshot, forward: Vec3): AimSample {
    if (input.wasPressed('primary')) {
      this.charging = true;
      this.power = 0;
      this.anchorX = input.pointer.x;
      this.anchorY = input.pointer.y;
      this.direction = forward;
    }
    if (this.charging) {
      const dx = input.pointer.x - this.anchorX;
      const dy = input.pointer.y - this.anchorY;
      const drag = Math.hypot(dx, dy);
      this.power = Math.min(1, drag / MAX_DRAG_PIXELS);
      if (drag >= MIN_DRAG_PIXELS) {
        const right = { x: -forward.z, z: forward.x };
        this.direction = normalize(forward.x * dy - right.x * dx, forward.z * dy - right.z * dx);
      }
    }
    return this.finish(input.wasReleased('primary'));
  }

  private updateCharge(dt: number, input: InputSnapshot, forward: Vec3): AimSample {
    this.direction = forward;
    if (!this.charging && (input.wasPressed('primary') || input.wasPressed('confirm-shot'))) {
      this.charging = true;
      this.power = 0;
      this.chargingUp = true;
    }
    if (this.charging) {
      const step = CHARGE_SECONDS > 0 ? Math.max(0, dt) / CHARGE_SECONDS : 1;
      this.power += this.chargingUp ? step : -step;
      if (this.power >= 1) {
        this.power = 1;
        this.chargingUp = false;
      } else if (this.power <= 0) {
        this.power = 0;
        this.chargingUp = true;
      }
    }
    return this.finish(input.wasReleased('primary') || input.wasReleased('confirm-shot'));
  }

  private finish(released: boolean): AimSample {
    let fired = false;
    if (this.charging && released) {
      this.charging = false;
      fired = this.power >= MIN_SHOT_POWER;
      if (!fired) this.power = 0;
    }
    return { direction: this.direction, power: this.power, charging: this.charging, fired };
  }
}
